namespace SvcSystems.AI.AgentClientProtocol;/// <summary>Options for starting an ACP agent as a child process.</summary>public sealed class ProcessOptions{    /// <summary>Executable to launch.</summary>    public required string FileName { get; init; }    /// <summary>Arguments passed to the executable without shell parsing.</summary>    public IReadOnlyList<string> Arguments { get; init; } = [];    /// <summary>Initial working directory for the agent process.</summary>    public string? WorkingDirectory { get; init; }    /// <summary>Environment variables added to or overridden in the child process.</summary>    public IReadOnlyDictionary<string, string?> Environment { get; init; } =        new Dictionary<string, string?>();    /// <summary>Maximum accepted UTF-8 byte length for one stdio protocol frame.</summary>    public int MaximumMessageBytes { get; init; } = 8 * 1024 * 1024;    /// <summary>Maximum time to wait for a child process to exit during disposal.</summary>    public TimeSpan ShutdownTimeout { get; init; } = TimeSpan.FromSeconds(3);    /// <summary>Receives stderr lines from the agent. Stderr is never treated as protocol traffic.</summary>    public Action<string>? StandardErrorReceived { get; init; }}